void EditorFrame::CompleteAsset(WorkResult& r){if(r.command==ExportSelectedPng){ImageSaved(r.path);return;}if(r.revision!=revision_||r.expected!=Selection()){status_.SetWindowText(Tr(Text::Busy));return;}if(r.command==StickerLibrary){CompleteImagePaste(r);return;}if(r.command==PictureAlphaSelection){if(r.maskEpoch!=maskEpoch_||style_.tool!=core::Tool::PixelSelect)return;const bool empty=r.mask&&r.mask->bounds.IsRectEmpty();CompleteMask(r);if(empty)status_.SetWindowText(Tr(Text::SelectionEmpty));return;}if(r.command==PictureFilters){if(!r.colorChanged){status_.SetWindowText(Tr(Text::ColorFilterUnchanged));return;}CommitComposition(std::move(r.state),r.expected);if(r.recipe)RememberRecipe(*r.recipe);}}
